1	// Type definitions mirror the data model in PROJECT_PLAN.md §6.
2	// These types are intentionally explicit; we prefer verbosity over guesswork
3	// because every number displayed must be traceable.
4	
5	export type Powertrain = "BEV" | "PHEV" | "EREV";
6	export type DrivetrainVariant = "SINGLE_MOTOR" | "AWD";
7	export type PortType = "NACS" | "CCS1" | "CCS2" | "CHAdeMO" | "J1772_ONLY";
8	export type BatteryChemistry = "LFP" | "NMC" | "NCA" | "LMR" | "UNKNOWN";
9	export type Confidence = "High" | "Medium" | "Low";
10	export type BodyStyle =
11	  | "Sedan"
12	  | "Hatchback"
13	  | "SUV"
14	  | "Crossover"
15	  | "Truck"
16	  | "Minivan"
17	  | "Wagon";
18	export type RangeTestProtocol = "EPA" | "WLTP" | "NRCan" | "RealWorld";
19	
20	export interface Source {
21	  url: string;
22	  name: string;
23	  accessed: string; // ISO date
24	}
25	
26	/** A single data point (e.g. range at 20C) with its provenance. */
27	export interface CitedValue<T> {
28	  value: T | null;
29	  source?: Source;
30	  confidence: Confidence;
31	  notes?: string;
32	}
33	
34	export interface Brand {
35	  id: string;
36	  name: string;
37	  country: string;
38	}
39	
40	export interface ThermalPoint {
41	  temp_c: number;
42	  value: number;
43	  source?: Source;
44	}
45	
46	export interface ChargingCurvePoint {
47	  soc_pct: number;
48	  kw: number;
49	}
50	
51	export interface Vehicle {
52	  id: string;
53	  brand_id: string;
54	  model: string;
55	  generation_label: string; // e.g. "Highland (2024+)"
56	  year_start: number;
57	  year_end: number | null; // null = current
58	  powertrain: Powertrain;
59	  body_style: BodyStyle;
60	  drivetrain_variant: DrivetrainVariant;
61	  trim_label: string; // e.g. "Long Range RWD"
62	
63	  // Core specs
64	  battery_kwh_total: CitedValue<number>;
65	  battery_kwh_usable: CitedValue<number>;
66	  battery_chemistry: BatteryChemistry;
67	  range_km: CitedValue<number>;
68	  range_protocol: RangeTestProtocol;
69	  ac_charge_kw_max: CitedValue<number>;
70	  dc_charge_kw_max: CitedValue<number>;
71	  port_type: PortType;
72	  seats: number;
73	  cargo_l_seats_up: CitedValue<number> | null;
74	  cargo_l_seats_down: CitedValue<number> | null;
75	  tow_rating_kg: CitedValue<number> | null;
76	  weight_kg: CitedValue<number> | null;
77	
78	  // Thermal / physics model inputs (for Phase 3 slider)
79	  has_heat_pump: CitedValue<boolean>;
80	  thermal_management: "active_liquid" | "passive" | "active_refrigerant" | "UNKNOWN";
81	
82	  // Per-vehicle thermal profile overrides (populated in Cluster B1).
83	  // All optional — thermal.ts falls back to chemistry-based defaults when absent.
84	  cold_derate_curve?: ThermalPoint[];     // capacity fraction vs ambient temp
85	  hvac_draw_kw_by_temp?: ThermalPoint[];  // HVAC draw (kW) vs ambient temp
86	  hp_min_temp_c?: number;                 // heat pump cutoff; below this → resistive
87	  precon_time_by_temp?: ThermalPoint[];   // minutes to precondition vs ambient temp
88	  precon_thermal_gain?: number;           // fraction of cold-soak DC derate recovered by precon
89	  dc_cold_soak_curve?: ThermalPoint[];    // DC peak factor vs temp when cold-soaked (800V advantage)
90	
91	  // Charging curve (20C baseline; more curves added in Phase 3)
92	  charging_curve_20c: ChargingCurvePoint[];
93	
94	  // Pricing
95	  msrp_cad: CitedValue<number>;
96	  federal_izev_cad: CitedValue<number>;
97	  provincial_rebate_cad_on: CitedValue<number>;
98	
99	  // Battery degradation (fleet-average annual range loss fraction; Recurrent data)
100	  degradation_annual?: number; // default 0.02 (2%/yr) when absent
101	
102	  // Overall vehicle data confidence (summary of per-field confidence)
103	  overall_confidence: Confidence;
104	  notes?: string;
105	}
106	
107	export interface Dataset {
108	  schema_version: string;
109	  generated_at: string;
110	  brands: Brand[];
111	  vehicles: Vehicle[];
112	}
113
